window.ChapterSpec={"scope": "原创交互导读，覆盖本章主节与精选定量模型；不复刻原书全文、原图或全部推导。各实验的背景与近似分别声明，不组成一套统一研究模拟。伴读生成可复制的参数化问题，未提供在线模型回答。", "number": 9, "title": "恒星形成", "headline": "从一团云，\n到一群恒星", "lede": "气体变冷之后，为什么仍不能立刻成为恒星？从支持与坍缩的竞争，走向效率、质量分布和反馈。", "pages": [417, 448], "sections": [{"id": "clouds", "num": "9.1", "title": "分子云不是一团均匀的冷气体", "pages": [418, 420], "paragraphs": ["星际介质包含多种温度、密度和电离状态。巨分子云的谱线、大小、速度弥散与质量估计，揭示了层级结构；一个平均密度不能代表所有正在形成恒星的致密核。", "热Jeans尺度给出引力与压力竞争的理想起点，维里参数则把整体随机运动和束缚放在同一本账中。两者依赖不同的结构与边界假设，不能互相替代。"], "labs": ["jeans", "cloud"]}, {"id": "molecules", "num": "9.2", "title": "先有分子和遮蔽，再问云怎样形成", "pages": [421, 424], "paragraphs": ["尘埃表面能促进H₂形成，紫外光则能解离它；自遮蔽与尘埃遮蔽使形成和破坏相互关联。这里不把一个人为临界密度当作已经求解的分子化学网络。", "热不稳定、盘的引力不稳定、湍流汇聚和大尺度流动都可能组织致密气体。分子含量与恒星形成相关，并不证明“变成分子”是唯一决定步骤。"], "labs": []}, {"id": "efficiency-section", "num": "9.3", "title": "磁场、湍流与反馈，控制的是哪些时钟", "pages": [425, 428], "paragraphs": ["磁支撑与磁通扩散、湍流支持与局部压缩、年轻恒星的注能，都可能改变云的寿命与形成效率。湍流既能增大整体速度弥散，也能在激波中压出高密度尾部。", "每自由落体效率是一种有用的统计描述。它不会自行解释其数值，更不能把所有云都设成恰好一个自由落体时间内完成坍缩。"], "labs": ["magnetic", "efficiency"]}, {"id": "individual", "num": "9.4", "title": "从致密核到年轻恒星", "pages": [429, 433], "paragraphs": ["低质量星的形成经历核心坍缩、吸积与前主序收缩。角动量、磁场和盘使真实流动偏离球对称；氢分子解离与辐射输运也影响阶段转换。", "大质量星强烈的辐射与电离反馈会改变周围气体。球对称辐射压力估计不能直接当作严格恒星质量上限，盘和各向异性会改变物质供应。"], "labs": ["hii"]}, {"id": "laws", "num": "9.5", "title": "经验定律连接的是尺度平均", "pages": [433, 439], "paragraphs": ["面密度关系、局部分子气体关系与体密度自由落体估计，使用的体积、时间平均和气体定义各不相同。将某个星系的全局经验斜率直接搬到每一团云，容易混淆因果与统计。", "恒星形成阈值还与盘动力学、分子比例和观测选择有关。可把本章效率与第11章局部盘稳定性一起比较，但不能由单个Q或单条KS关系决定全部形成活动。"], "labs": ["ks"]}, {"id": "mass-function", "num": "9.6", "title": "IMF，是光和反馈预算的共同起点", "pages": [440, 445], "paragraphs": ["形成率的观测标定、星族光度和超新星预算，都依赖初始质量分布。需要先说明dN/dm还是dN/dlnm、质量上下限和归一化，才能比较斜率与高质量份额。", "IMF的低质量转折、环境差异和理论起源，不能由本页单幂律实验解决。后续章节将继续使用明确的质量预算，避免把数量份额当质量份额。"], "labs": ["imf"]}, {"id": "first-stars", "num": "9.7", "title": "第一代恒星，面对不同的冷却通道", "pages": [446, 448], "paragraphs": ["无金属、少尘埃的早期气体主要依赖气相分子反应与H₂冷却；原子冷却阈值、辐射背景和反馈共同影响能否形成致密核。早期恒星的特征质量不能仅凭一个维里温度确定。", "CMB为低温过程提供随红移变化的背景。降低冷却效率会影响碎裂尺度，但本章Jeans实验不含原始化学网络，不能直接预报Population III的IMF。"], "labs": []}], "labs": [{"id": "jeans", "model": "jeans", "title": "一团冷气体，何时压不住引力", "intro": "固定均匀分子气体的温度与密度，比较热Jeans长度、质量和自由落体时标。降温与增密都能缩小不稳定尺度。", "params": [{"key": "n", "label": "log₁₀ 总粒子密度 n / cm⁻³", "min": 2, "max": 6, "step": 0.1, "value": 3, "digits": 2}, {"key": "T", "label": "温度 T（K）", "min": 10, "max": 200, "step": 5, "value": 20, "digits": 2}], "values": ["Jeans长度（pc）", "Jeans质量（M☉）", "tff（Myr）"], "pages": [419, 420], "formula": "cs²=kBT/(μmₚ)，ρ=μmₚn，μ=2.33<br>λJ=cs√[π/(Gρ)]，MJ=(π/6)ρλJ³<br>tff=√[3π/(32Gρ)]", "assumptions": "均匀分子气体、等温声速、热支持，μ=2.33含氦。n为总粒子密度，非nH或nH₂。忽略湍流、磁场、边界压力与有限云结构；Jeans条件不是每个GMC必然成星的保证。", "scene": true, "ref": "9.1 · MBW (2010) pp.419–420", "formulaTex": ["c_s^2=\\frac{k_{\\mathrm B}T}{\\mu m_p},\\quad \\rho=\\mu m_p n,\\quad\\mu=2.33", "\\lambda_{\\mathrm J}=c_s\\sqrt{\\frac{\\pi}{G\\rho}}", "M_{\\mathrm J}=\\frac{\\pi}{6}\\rho\\lambda_{\\mathrm J}^3", "t_{\\mathrm{ff}}=\\sqrt{\\frac{3\\pi}{32G\\rho}}"]}, {"id": "cloud", "model": "cloud", "title": "速度弥散，是支持还是坍缩线索", "intro": "对均匀球计算维里比与总能量符号。速度弥散只作为各向同性一维随机速度输入，不把它自动解释成热温度。", "params": [{"key": "mass", "label": "log₁₀ 云质量 / M☉", "min": 3, "max": 6, "step": 0.1, "value": 5, "digits": 2}, {"key": "R", "label": "云半径（pc）", "min": 1, "max": 100, "step": 1, "value": 20, "digits": 2}, {"key": "sigma", "label": "一维 σ（km/s）", "min": 0.2, "max": 10, "step": 0.2, "value": 2, "digits": 2}], "values": ["αvir=2K/|W|", "tff（Myr）", "表面逃逸速度（km/s）"], "pages": [419, 420], "formula": "K=3Mσ²/2，W=−3GM²/(5R)<br>αvir=5σ²R/(GM)，vesc=√(2GM/R)", "assumptions": "孤立均匀球、无表面项，σ为总一维支持速度，未再加一次热声速。αvir=1为维里平衡关系，αvir=2才是此模型零总能量边界；真实受压、磁化和非平衡云不必照此分类。", "scene": true, "ref": "9.1 · MBW (2010) pp.419–420", "formulaTex": ["K=\\frac32M\\sigma^2,\\quad W=-\\frac{3GM^2}{5R}", "\\alpha_{\\mathrm{vir}}=\\frac{5\\sigma^2R}{GM}", "v_{\\mathrm{esc}}=\\sqrt{\\frac{2GM}{R}}"]}, {"id": "magnetic", "model": "magnetic", "title": "磁通与质量，要一起比较", "intro": "保持云面积，比较质量与指定几何约定下的磁临界质量。磁场强不等于所有方向上的引力都被阻止。", "params": [{"key": "mass", "label": "log₁₀ 云质量 / M☉", "min": 3, "max": 6, "step": 0.1, "value": 4, "digits": 2}, {"key": "R", "label": "磁通截面半径（pc）", "min": 1, "max": 20, "step": 0.5, "value": 5, "digits": 2}, {"key": "B", "label": "穿过截面的 B（μG）", "min": 0.1, "max": 100, "step": 0.1, "value": 10, "digits": 2}], "values": ["磁临界质量（M☉）", "M / MΦ", "临界 B（μG）"], "pages": [425, 426], "formula": "Φ=πR²B，MΦ=Φ/(2π√G)<br>μΦ=M/MΦ", "assumptions": "这是常用理想质量—磁通临界约定，几何系数与原书均匀球估算不完全相同。磁通冻结、场方向、非理想扩散和湍流都影响结论；不把MΦ与MJ直接相加成精确支撑质量。", "scene": true, "ref": "9.3 · MBW (2010) pp.425–426", "formulaTex": ["\\Phi=\\pi R^2B", "M_\\Phi=\\frac{\\Phi}{2\\pi\\sqrt G},\\quad \\mu_\\Phi=\\frac{M}{M_\\Phi}"]}, {"id": "efficiency", "model": "efficiency", "title": "一个自由落体时间，并不会吃完所有气体", "intro": "用指定的每自由落体效率积分封闭气体库，观察小效率如何拉长气体耗尽时间。", "params": [{"key": "mass", "label": "log₁₀ 初始气体质量 / M☉", "min": 5, "max": 8, "step": 0.1, "value": 6, "digits": 2}, {"key": "n", "label": "log₁₀ 总粒子密度 / cm⁻³", "min": 2, "max": 5, "step": 0.1, "value": 3, "digits": 2}, {"key": "eps", "label": "每自由落体效率 εff", "min": 0.003, "max": 0.05, "step": 0.001, "value": 0.01, "digits": 3}, {"key": "time", "label": "经过时间（Myr）", "min": 0, "max": 20, "step": 0.1, "value": 5, "digits": 2}], "values": ["当前形成率（M☉/yr）", "锁定恒星份额（%）", "耗尽时间（Myr）"], "pages": [425, 428], "formula": "dMg/dt=−εff Mg/tff<br>Mg/M₀=exp(−εff t/tff)，tdep=tff/εff", "assumptions": "固定由初始密度计算的tff，形成质量全部锁定，忽略回流、补给、反馈与密度变化。这是效率的定义性动力学类比，不解释真实εff的唯一来源。", "scene": true, "ref": "9.3 · MBW (2010) pp.425–428", "sweep": "time", "formulaTex": ["\\frac{dM_g}{dt}=-\\frac{\\epsilon_{\\mathrm{ff}}M_g}{t_{\\mathrm{ff}}}", "\\frac{M_g}{M_0}=\\exp\\!\\left(-\\frac{\\epsilon_{\\mathrm{ff}}t}{t_{\\mathrm{ff}}}\\right)", "t_{\\mathrm{dep}}=\\frac{t_{\\mathrm{ff}}}{\\epsilon_{\\mathrm{ff}}}"]}, {"id": "ks", "model": "ks", "title": "从气体面密度，到经验形成率", "intro": "改变幂律斜率，比较全局面密度经验关系与气体耗尽时间。每平方pc和每平方kpc不能混用。", "params": [{"key": "Sigma", "label": "Σgas（M☉/pc²）", "min": 1, "max": 1000, "step": 1, "value": 20, "digits": 2}, {"key": "N", "label": "经验幂律斜率 N", "min": 1, "max": 1.8, "step": 0.05, "value": 1.4, "digits": 2}], "values": ["ΣSFR（M☉ yr⁻¹ kpc⁻²）", "耗尽时间（Gyr）", "幂律斜率"], "pages": [434, 439], "formula": "ΣSFR=2.5×10⁻⁴(Σgas/[M☉ pc⁻²])ᴺ<br>tdep=10⁶Σgas/ΣSFR yr", "assumptions": "归一化参考教材讨论的全局Kennicutt关系，气体约定不加额外氦修正；N=1.4为参考，改变N是教学比较而非重新拟合数据。未计算散布、分子比例或局部阈值。", "scene": false, "ref": "9.5 · MBW (2010) pp.434–439", "formulaTex": ["\\Sigma_{\\mathrm{SFR}}=2.5\\times10^{-4}\\left(\\frac{\\Sigma_{\\mathrm{gas}}}{M_\\odot\\,\\mathrm{pc}^{-2}}\\right)^N M_\\odot\\,\\mathrm{yr}^{-1}\\,\\mathrm{kpc}^{-2}", "\\frac{t_{\\mathrm{dep}}}{\\mathrm{yr}}=10^6\\frac{\\Sigma_{\\mathrm{gas}}/(M_\\odot\\,\\mathrm{pc}^{-2})}{\\Sigma_{\\mathrm{SFR}}/(M_\\odot\\,\\mathrm{yr}^{-1}\\,\\mathrm{kpc}^{-2})}"]}, {"id": "imf", "model": "imf", "title": "相同形成质量，恒星个数可以不同", "intro": "将单幂律IMF按初始质量归一化，分别查看高质量份额、前身个数和平均恒星质量。", "params": [{"key": "slope", "label": "dN/dm∝m⁻ˢ 的指数 s", "min": 1, "max": 3, "step": 0.05, "value": 2.35, "digits": 2}, {"key": "cut", "label": "检查质量下限（M☉）", "min": 0.1, "max": 30, "step": 0.1, "value": 8, "digits": 2}], "values": ["高于下限的质量份额（%）", "每1000M☉的>8M☉前身数", "平均恒星质量（M☉）"], "pages": [440, 445], "formula": "φ(m)=C m⁻ˢ，0.1≤m/M☉≤100<br>∫mφ(m)dm=1M☉<br>dN/d ln m=mφ(m)", "assumptions": "Salpeter单幂律在全质量区间的延伸是教学假设，并非实测低质量IMF。按质量与按个数的份额不同；简化8M☉前身阈值不能替代超新星类型或遗迹模型。", "scene": true, "ref": "9.6 · MBW (2010) pp.440–445", "formulaTex": ["\\phi(m)=Cm^{-s},\\quad 0.1\\le\\frac m{M_\\odot}\\le100", "\\int_{0.1}^{100}m\\phi(m)\\,dm=1", "\\frac{dN}{d\\ln m}=m\\phi(m),\\quad m\\ \\text{in}\\ M_\\odot"]}, {"id": "hii", "model": "stromgren", "title": "一颗热星，能维持多大的电离区", "intro": "在固定密度纯氢介质中平衡光电离与复合，观察电离前沿接近Strömgren半径。", "params": [{"key": "Q", "label": "log₁₀ 电离光子率 / s⁻¹", "min": 47, "max": 50, "step": 0.1, "value": 49, "digits": 2}, {"key": "n", "label": "log₁₀ nH / cm⁻³", "min": 1, "max": 4, "step": 0.1, "value": 2, "digits": 2}, {"key": "tau", "label": "时间 / trec", "min": 0, "max": 5, "step": 0.05, "value": 1, "digits": 2}], "values": ["Strömgren半径（pc）", "当前电离半径（pc）", "复合时标（kyr）"], "pages": [432, 433], "formula": "RS=[3Q/(4παB nH²)]¹ᐟ³<br>trec=(αB nH)⁻¹<br>R(t)=RS[1−exp(−t/trec)]¹ᐟ³", "assumptions": "纯氢、T=10⁴K、case-B αB=2.6×10⁻¹³cm³/s、恒定Q和密度。作为大质量星电离反馈的新增局部推导，不包括气体压力膨胀、尘埃、逃逸与辐射流体耦合。", "scene": true, "ref": "9.4 · MBW (2010) pp.432–433", "sweep": "tau", "formulaTex": ["R_{\\mathrm S}=\\left(\\frac{3Q}{4\\pi\\alpha_{\\mathrm B}n_{\\mathrm H}^2}\\right)^{1/3}", "t_{\\mathrm{rec}}=\\frac1{\\alpha_{\\mathrm B}n_{\\mathrm H}}", "R(t)=R_{\\mathrm S}\\left(1-e^{-t/t_{\\mathrm{rec}}}\\right)^{1/3}"]}], "quiz": [{"q": "Jeans质量下降，能否保证整座真实GMC立刻成星？", "options": ["能，热支持是唯一因素", "不能，还需要结构、边界和其他支持信息"], "answer": 1, "why": "Jeans推导采用均匀热气体，真实云有湍流、磁场和时间演化。"}, {"q": "在孤立均匀球模型中，零总能量对应哪一个αvir？", "options": ["1", "2"], "answer": 1, "why": "αvir=2K/|W|，E=K−|W|=0时αvir=2。"}, {"q": "εff很小意味着什么？", "options": ["耗尽时间可以远长于tff", "自由落体时间必定不存在"], "answer": 0, "why": "指定效率模型中tdep=tff/εff。"}, {"q": "IMF的质量份额与数量份额相同吗？", "options": ["相同", "不同，高质量星更重但通常更少"], "answer": 1, "why": "两个积分分别以mφ与φ加权。"}, {"q": "本页HII前沿的推进等于气体整体膨胀吗？", "options": ["等于", "不等于，这里密度固定，只平衡电离与复合"], "answer": 1, "why": "Strömgren模型没有求解气体压力运动。"}, {"q": "改变KS斜率，是在重新拟合观测吗？", "options": ["是", "不是，本页只做指定参数比较"], "answer": 1, "why": "模型没有接入观测目录或拟合误差。"}], "errata": "采用明确的分子或纯氢成分约定；不同实验的n定义在控件旁分别列出。"};
window.BookSources={"chapter-9": {"title": "恒星形成", "pages": "417–448", "pdf": "439–470", "section": "第9章", "body": "原创交互导读，覆盖本章主节与精选定量模型；不复刻原书全文、原图或全部推导。各实验的背景与近似分别声明，不组成一套统一研究模拟。伴读生成可复制的参数化问题，未提供在线模型回答。"}, "clouds": {"title": "分子云不是一团均匀的冷气体", "pages": "418–420", "pdf": "440–442", "section": "9.1", "body": "星际介质包含多种温度、密度和电离状态。巨分子云的谱线、大小、速度弥散与质量估计，揭示了层级结构；一个平均密度不能代表所有正在形成恒星的致密核。 热Jeans尺度给出引力与压力竞争的理想起点，维里参数则把整体随机运动和束缚放在同一本账中。两者依赖不同的结构与边界假设，不能互相替代。 以上为原创导读，不是原书全文。"}, "molecules": {"title": "先有分子和遮蔽，再问云怎样形成", "pages": "421–424", "pdf": "443–446", "section": "9.2", "body": "尘埃表面能促进H₂形成，紫外光则能解离它；自遮蔽与尘埃遮蔽使形成和破坏相互关联。这里不把一个人为临界密度当作已经求解的分子化学网络。 热不稳定、盘的引力不稳定、湍流汇聚和大尺度流动都可能组织致密气体。分子含量与恒星形成相关，并不证明“变成分子”是唯一决定步骤。 以上为原创导读，不是原书全文。"}, "efficiency-section": {"title": "磁场、湍流与反馈，控制的是哪些时钟", "pages": "425–428", "pdf": "447–450", "section": "9.3", "body": "磁支撑与磁通扩散、湍流支持与局部压缩、年轻恒星的注能，都可能改变云的寿命与形成效率。湍流既能增大整体速度弥散，也能在激波中压出高密度尾部。 每自由落体效率是一种有用的统计描述。它不会自行解释其数值，更不能把所有云都设成恰好一个自由落体时间内完成坍缩。 以上为原创导读，不是原书全文。"}, "individual": {"title": "从致密核到年轻恒星", "pages": "429–433", "pdf": "451–455", "section": "9.4", "body": "低质量星的形成经历核心坍缩、吸积与前主序收缩。角动量、磁场和盘使真实流动偏离球对称；氢分子解离与辐射输运也影响阶段转换。 大质量星强烈的辐射与电离反馈会改变周围气体。球对称辐射压力估计不能直接当作严格恒星质量上限，盘和各向异性会改变物质供应。 以上为原创导读，不是原书全文。"}, "laws": {"title": "经验定律连接的是尺度平均", "pages": "433–439", "pdf": "455–461", "section": "9.5", "body": "面密度关系、局部分子气体关系与体密度自由落体估计，使用的体积、时间平均和气体定义各不相同。将某个星系的全局经验斜率直接搬到每一团云，容易混淆因果与统计。 恒星形成阈值还与盘动力学、分子比例和观测选择有关。可把本章效率与第11章局部盘稳定性一起比较，但不能由单个Q或单条KS关系决定全部形成活动。 以上为原创导读，不是原书全文。"}, "mass-function": {"title": "IMF，是光和反馈预算的共同起点", "pages": "440–445", "pdf": "462–467", "section": "9.6", "body": "形成率的观测标定、星族光度和超新星预算，都依赖初始质量分布。需要先说明dN/dm还是dN/dlnm、质量上下限和归一化，才能比较斜率与高质量份额。 IMF的低质量转折、环境差异和理论起源，不能由本页单幂律实验解决。后续章节将继续使用明确的质量预算，避免把数量份额当质量份额。 以上为原创导读，不是原书全文。"}, "first-stars": {"title": "第一代恒星，面对不同的冷却通道", "pages": "446–448", "pdf": "468–470", "section": "9.7", "body": "无金属、少尘埃的早期气体主要依赖气相分子反应与H₂冷却；原子冷却阈值、辐射背景和反馈共同影响能否形成致密核。早期恒星的特征质量不能仅凭一个维里温度确定。 CMB为低温过程提供随红移变化的背景。降低冷却效率会影响碎裂尺度，但本章Jeans实验不含原始化学网络，不能直接预报Population III的IMF。 以上为原创导读，不是原书全文。"}, "jeans": {"title": "一团冷气体，何时压不住引力", "pages": "419–420", "pdf": "441–442", "section": "9.1 · MBW (2010) pp.419–420", "body": "均匀分子气体、等温声速、热支持，μ=2.33含氦。n为总粒子密度，非nH或nH₂。忽略湍流、磁场、边界压力与有限云结构；Jeans条件不是每个GMC必然成星的保证。"}, "cloud": {"title": "速度弥散，是支持还是坍缩线索", "pages": "419–420", "pdf": "441–442", "section": "9.1 · MBW (2010) pp.419–420", "body": "孤立均匀球、无表面项，σ为总一维支持速度，未再加一次热声速。αvir=1为维里平衡关系，αvir=2才是此模型零总能量边界；真实受压、磁化和非平衡云不必照此分类。"}, "magnetic": {"title": "磁通与质量，要一起比较", "pages": "425–426", "pdf": "447–448", "section": "9.3 · MBW (2010) pp.425–426", "body": "这是常用理想质量—磁通临界约定，几何系数与原书均匀球估算不完全相同。磁通冻结、场方向、非理想扩散和湍流都影响结论；不把MΦ与MJ直接相加成精确支撑质量。"}, "efficiency": {"title": "一个自由落体时间，并不会吃完所有气体", "pages": "425–428", "pdf": "447–450", "section": "9.3 · MBW (2010) pp.425–428", "body": "固定由初始密度计算的tff，形成质量全部锁定，忽略回流、补给、反馈与密度变化。这是效率的定义性动力学类比，不解释真实εff的唯一来源。"}, "ks": {"title": "从气体面密度，到经验形成率", "pages": "434–439", "pdf": "456–461", "section": "9.5 · MBW (2010) pp.434–439", "body": "归一化参考教材讨论的全局Kennicutt关系，气体约定不加额外氦修正；N=1.4为参考，改变N是教学比较而非重新拟合数据。未计算散布、分子比例或局部阈值。"}, "imf": {"title": "相同形成质量，恒星个数可以不同", "pages": "440–445", "pdf": "462–467", "section": "9.6 · MBW (2010) pp.440–445", "body": "Salpeter单幂律在全质量区间的延伸是教学假设，并非实测低质量IMF。按质量与按个数的份额不同；简化8M☉前身阈值不能替代超新星类型或遗迹模型。"}, "hii": {"title": "一颗热星，能维持多大的电离区", "pages": "432–433", "pdf": "454–455", "section": "9.4 · MBW (2010) pp.432–433", "body": "纯氢、T=10⁴K、case-B αB=2.6×10⁻¹³cm³/s、恒定Q和密度。作为大质量星电离反馈的新增局部推导，不包括气体压力膨胀、尘埃、逃逸与辐射流体耦合。"}};
